const $=id=>document.getElementById(id),html=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,projects=[],p=null,route='projects',mode='image',guide=null,status={runtime:false},urls=[],undo=[],saving,busy=false,job=null,pollTimer,importKind='image',selectionEpoch=0;
const toast=message=>{const el=$('toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',5500);};
const wrap=fn=>async(...args)=>{try{await fn(...args);}catch(e){console.error(e);toast(e.message||'Something went wrong. Your project is kept.');}};
const on=(id,fn,event='click')=>{if($(id))$(id).addEventListener(event,wrap(fn));};
