const dataURL=b=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(b);});
const blobCanvas=canvas=>new Promise(resolve=>canvas.toBlob(resolve,'image/png'));
const download=(blob,name)=>{const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);};
const jsonBlob=x=>new Blob([JSON.stringify(x,null,2)],{type:'application/json'});
async function openDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('shotfix-studio-v3',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Browser storage is unavailable. Allow site storage to save projects.'));});projects=await store('readonly',s=>s.getAll());}
