async function save(){if(!p?.posterBlob)return;p.updatedAt=new Date().toISOString();await store('readwrite',s=>s.put(clone(p)));const index=projects.findIndex(x=>x.id===p.id);if(index<0)projects.push(p);else projects[index]=p;$('saveStatus').textContent='Saved on this device';}
