function selected(){return p?.takes.find(t=>t.id===p.selectedTake&&t.sourceId===p.sourceId);}
function currentTakes(){return (p?.takes||[]).filter(t=>t.sourceId===p.sourceId&&t.kind===mode&&(mode!=='video'||!t.parentTakeId||t.parentTakeId===p.videoImageId));}
function newProject(){selectionEpoch++;p={id:crypto.randomUUID(),sourceId:crypto.randomUUID(),name:'Untitled shot',references:[],takes:[],camera:{az:0,el:5,focal:35,distance:6},range:{start:0,end:4},seconds:4,createdAt:new Date().toISOString()};undo=[];mode='image';route='input';render();}
function header(){ $('demoBadge').hidden=!p?.demoMode;$('demoBadge').textContent=p?.demoMedia?.verified?'Recorded workflow · no credits':'Demo mode · no credits'; $('breadcrumb').textContent=route==='projects'?'Projects':p?.name||'New shot';$('undo').hidden=route!=='editor'||mode!=='image';$('exportProject').hidden=!p?.posterBlob;$('videoMode').hidden=true;$('videoMode').textContent=mode==='image'?'Create video →':'← Image editor';$('videoMode').disabled=mode==='image'&&!p?.takes.some(t=>t.sourceId===p.sourceId&&t.kind==='image');$('saveStatus').textContent=route==='projects'?'':(p?.posterBlob?'Saved on this device':'');}
