function rangeHTML(){const duration=Math.floor(p.duration);return `<div class="stack" style="margin-top:16px"><div class="row"><span class="range-label">Source range</span><span class="range-values" id="rangeValue">${p.range.start.toFixed(0)}–${p.range.end.toFixed(0)} s · ${(p.range.end-p.range.start).toFixed(0)} s</span></div><div class="range-inputs"><label>In<input id="rangeStart" type="range" min="0" max="${Math.max(0,duration-4)}" step="1" value="${p.range.start}"><output id="inValue">${p.range.start}s</output></label><label>Out<input id="rangeEnd" type="range" min="${Math.min(4,duration)}" max="${duration}" step="1" value="${p.range.end}"><output id="outValue">${p.range.end}s</output></label></div></div>`;}
function bindRanges(){for(const id of['rangeStart','rangeEnd'])on(id,e=>{const d=Math.floor(p.duration);if(id==='rangeStart'){p.range.start=Math.min(+e.target.value,p.range.end-4);}else p.range.end=Math.max(+e.target.value,p.range.start+4);p.range.start=Math.max(0,p.range.start);p.range.end=Math.min(d,p.range.end);$('rangeStart').value=p.range.start;$('rangeEnd').value=p.range.end;$('inValue').textContent=p.range.start+'s';$('outValue').textContent=p.range.end+'s';$('rangeValue').textContent=`${p.range.start}–${p.range.end} s · ${p.range.end-p.range.start} s`;queueSave();},'input');}
