async function frameCanvas(blob){const u=URL.createObjectURL(blob),image=new Image();try{image.src=u;await image.decode();const c=document.createElement('canvas');const scale=Math.min(1,1280/image.width);c.width=Math.round(image.width*scale);c.height=Math.round(image.height*scale);c.getContext('2d').drawImage(image,0,0,c.width,c.height);return c;}finally{URL.revokeObjectURL(u);}}
async function loadSource(file){if(file.size>64*1024*1024)throw Error('Choose a file under 64 MB.');if(!/^(image\/(png|jpeg|webp)|video\/(mp4|webm))$/.test(file.type))throw Error('Choose PNG, JPG, WebP, MP4 or WebM.');const epoch=++selectionEpoch;let poster,width,height,duration=0,type=file.type.startsWith('video')?'video':'image';if(type==='image'){const c=await frameCanvas(file);poster=await blobCanvas(c);width=c.width;height=c.height;}else{const u=URL.createObjectURL(file),v=document.createElement('video');try{v.preload='auto';v.muted=true;v.src=u;await new Promise((resolve,reject)=>{v.onloadedmetadata=resolve;v.onerror=()=>reject(Error('This video codec cannot be read. Try H.264 MP4.'));});duration=v.duration;if(!Number.isFinite(duration)||duration<1||duration>600)throw Error('Choose a video between 1 second and 10 minutes.');await new Promise((resolve,reject)=>{v.onseeked=resolve;v.onerror=reject;v.currentTime=Math.min(.1,duration/2);});const c=document.createElement('canvas');const scale=Math.min(1,1280/v.videoWidth);c.width=Math.round(v.videoWidth*scale);c.height=Math.round(v.videoHeight*scale);c.getContext('2d').drawImage(v,0,0,c.width,c.height);poster=await blobCanvas(c);width=c.width;height=c.height;}finally{v.removeAttribute('src');v.load();URL.revokeObjectURL(u);}}
 if(epoch!==selectionEpoch)return;if(p?.sourceBlob){p={id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),references:[],takes:[],createdAt:new Date().toISOString()};}Object.assign(p,{sourceId:crypto.randomUUID(),sourceBlob:file,posterBlob:poster,sourceType:type,sourceName:file.name,name:file.name.replace(/\.[^.]+$/,''),width,height,duration,range:{start:0,end:Math.min(6,Math.floor(duration))},seconds:4,plan:null,selectedTake:null,example:false,camera:{az:0,el:5,focal:35,distance:6}});route='input';await save();render();}
async function buildGuide(){if(busy)return;busy=true;$('buildGuide').disabled=true;try{if(!p.plan){const c=await frameCanvas(p.posterBlob),small=document.createElement('canvas');small.width=240;small.height=Math.round(240*p.height/p.width);small.getContext('2d').drawImage(c,0,0,small.width,small.height);p.plan=estimatePlan(small);}route='editor';mode='image';await save();render();if(p.demoMode){p.demoGuideBuilt=true;await save();}toast(p.demoMode?'Prepared 3D guide loaded. Drag the camera to compose your shot.':p.example?'Prepared example guide. Drag to change the camera.':'Local layout draft ready. Use Align to match the subject and background.');}finally{busy=false;}}
