async function resumeJob(id){clearTimeout(pollTimer);const projectId=p.id;try{job=await api('jobs/'+id);if(p?.id!==projectId)return;if(job.resultUrl){const r=await fetch(job.resultUrl);if(!r.ok)throw Error('Result download failed. Refresh the job; do not generate again.');const b=await r.blob(),snapshot=job.snapshot||{},t={id:job.id,kind:job.kind,origin:'generated',blob:b,camera:snapshot.camera||clone(p.camera),plan:snapshot.plan||clone(p.plan),sourceId:snapshot.sourceId||p.sourceId,parentTakeId:snapshot.parentTakeId||snapshot.selectedTakeId,videoMotion:snapshot.videoMotion,createdAt:job.createdAt};if(!p.takes.some(x=>x.id===t.id))p.takes.push(t);p.selectedTake=t.id;mode=t.kind;workspaceFocus='review';p.jobId=null;job=null;await save();render();return;}if(['failed','canceled','rejected'].includes(job.status)){toast(job.error||'Generation did not finish.');p.jobId=null;job=null;await save();render();return;}if(job.status==='unknown'){toast(job.error||'Verify the provider job before submitting again.');render();return;}const current=$('resultMedia')?.querySelector('.progress');if(current)current.outerHTML=progressHTML();else if($('resultMedia'))$('resultMedia').insertAdjacentHTML('beforeend',progressHTML());pollTimer=setTimeout(()=>resumeJob(id),5000);}catch(e){toast(e.message);if(p?.jobId===id)pollTimer=setTimeout(()=>resumeJob(id),10000);}}
