function fromData(uri){const [head,base]=uri.split(','),bytes=Uint8Array.from(atob(base),x=>x.charCodeAt(0));return new Blob([bytes],{type:head.match(/data:([^;]+)/)[1]});}
const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
function crc(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
async function zip(files){const parts=[],central=[];let offset=0;const enc=new TextEncoder();for(const [name,blob]of files){const bytes=new Uint8Array(await blob.arrayBuffer()),n=enc.encode(name),sum=crc(bytes),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,sum,true);v.setUint32(18,bytes.length,true);v.setUint32(22,bytes.length,true);v.setUint16(26,n.length,true);h.set(n,30);parts.push(h,bytes);const c=new Uint8Array(46+n.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,sum,true);cv.setUint32(20,bytes.length,true);cv.setUint32(24,bytes.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);c.set(n,46);central.push(c);offset+=h.length+bytes.length;}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
async function exportRequest(x,graph){const files=[['workflow.api.json',jsonBlob(graph)],['shotfix-settings.json',jsonBlob({kind:x.kind,camera:x.camera,plan:x.plan,sourceId:x.sourceId,selectedTakeId:x.selectedTakeId,range:x.range,seconds:x.seconds,note:x.note})]];if(x.kind==='image'){files.push(['source.png',fromData(x.source)],['guide.png',fromData(x.guide)]);x.references.forEach((r,i)=>files.push(['ref'+i+'.png',fromData(r)]));}else{files.push(['selected-take.png',fromData(x.selectedImage)],[x.guideVideo.startsWith('data:video/mp4')?'guide-video.mp4':'guide.webm',fromData(x.guideVideo)]);(x.references||[]).forEach((r,i)=>files.push(['ref'+i+'.png',fromData(r)]));if(x.originalVideo)files.push(['original-input.'+(x.originalVideo.startsWith('data:video/webm')?'webm':'mp4'),fromData(x.originalVideo)]);}
 const readme=`Shotfix generation package\n\nNo generation was executed by exporting this package. No key is included.\n\nImage: copy source.png, guide.png and ref*.png into your Comfy input folder, then submit workflow.api.json as an API-format graph.\n\nVideo: convert guide.webm to guide-video.mp4 using ffmpeg -i guide.webm -r 24 -pix_fmt yuv420p guide-video.mp4. If an original video exists, trim it to the saved range in shotfix-settings.json and save as original.mp4. Put selected-take.png, guide-video.mp4 and original.mp4 (if used) in your Comfy input directory.\n\nThe workflow uses partner API nodes and may use credits. Nano Banana 2.1 and Seedance 2.5 were tested separately in Comfy on the painter-workshop example. Execution through the app runtime has not been verified. Check nodes, model availability and cost before running.\n\nThe guide is a source-aligned approximate blockout, not exact 3D recovery. A static mannequin guide controls composition, not the original performance.\n\nOfficial templates: https://github.com/Comfy-Org/workflow_templates\n`;files.push(['README.txt',new Blob([readme],{type:'text/plain'})]);download(await zip(files),'shotfix-'+x.kind+'-package.zip');toast('Package saved. No generation or external upload was run.');}
async function exportProject(){if(!p?.posterBlob)return;const metadata=clone(p);delete metadata.sourceBlob;delete metadata.posterBlob;metadata.references=metadata.references.map(({blob,...r})=>r);metadata.takes=metadata.takes.map(({blob,...t})=>t);const files=[['project.json',jsonBlob(metadata)],['source-frame.png',p.posterBlob],['original.'+(p.sourceType==='video'?'mp4':'png'),p.sourceBlob]];p.references.forEach((r,i)=>files.push(['reference-'+i+'.png',r.blob]));p.takes.forEach(t=>files.push(['takes/'+t.id+(t.kind==='image'?'.png':'.mp4'),t.blob]));download(await zip(files),'shotfix-project-'+p.id.slice(0,8)+'.zip');}

async function loadPainterWorkshop(){
 const base='./assets/private/painter-workshop/';
 const [sceneResponse,mediaResponse]=await Promise.all([fetch(base+'scene.json'),fetch(base+'mock-media.json')]);
 if(!sceneResponse.ok||!mediaResponse.ok)throw Error('The local workshop assets are unavailable.');
 const metadata=await sceneResponse.json(),media=await mediaResponse.json();
 const existing=projects.find(x=>x.privateScene==='painter-workshop');
 if(existing?.demoRevision!==media.revision&&existing){existing.demoRevision=media.revision;existing.demoMedia=media;existing.posterBlob=await(await fetch(base+media.source.poster)).blob();existing.demoMode=true;}
 if(existing?.demoRevision===media.revision){p=clone(existing);p.sceneShots=metadata.shots;p.demoMedia=media;selectionEpoch++;mode='image';route=p.demoGuideBuilt?'editor':'input';await installVerifiedTakes();await save();render();return;}
 const assetBlob=async name=>{const r=await fetch(base+name);if(!r.ok)throw Error('Missing workshop asset: '+name);return r.blob();};
 const [source,poster,character]=await Promise.all([assetBlob(media.source.file),assetBlob(media.source.poster),assetBlob(media.character)]);
 newProject();if(existing)p=clone(existing);
 Object.assign(p,{sourceId:crypto.randomUUID(),privateScene:'painter-workshop',demoMode:true,demoRevision:media.revision,demoGuideBuilt:false,demoMedia:media,demoPreviewSeconds:1.25,name:'Painter workshop',sourceBlob:source,posterBlob:poster,sourceType:'video',sourceName:media.source.originalName,width:media.source.width,height:media.source.height,duration:media.source.duration,range:{start:0,end:Math.min(1.25,media.source.duration)},seconds:1.25,references:[{name:'Character sheet',blob:character}],example:false,sceneShots:metadata.shots,camera:clone(metadata.shots[0].camera),selectedTake:null,videoImageId:null,jobId:null,plan:validatePlan({version:1,asset:'painter-workshop',method:'reference-assisted-blockout',room:'studio',horizon:.45,subjects:[{kind:'person',x:.5,bottom:.91,height:.44,width:.17}]})});
 await installVerifiedTakes();await save();route='input';render();toast('Demo input: wide video + character sheet. Build the guide to start.');
}

async function installVerifiedTakes(){
 const v=p.demoMedia?.verified;if(!v||p.verifiedMediaRevision===3)return;
 const side=p.sceneShots.find(s=>s.id===v.shotId);if(!side)return;
 const base='./assets/private/painter-workshop/';
 const load=async name=>{const r=await fetch(base+name);if(!r.ok)throw Error('Missing recorded workflow result');return r.blob();};
 const image=takeSnapshot(p,await load(v.image),'image','workflow-result');image.camera=clone(side.camera);image.mockShotId=side.id;image.label='Verified Nano Banana preview';
 const video=takeSnapshot(p,await load(v.video),'video','workflow-result');video.camera=clone(side.camera);video.parentTakeId=image.id;video.mockShotId=side.id;video.duration=v.duration;video.label='Verified Seedance video';
 p.takes.push(image,video);p.selectedTake=image.id;p.videoImageId=image.id;p.verifiedMediaRevision=3;
}

function updateDemoShotButtons(){
 if(!p?.sceneShots)return;
 document.querySelectorAll('[data-workshop-shot]').forEach(el=>{const shot=p.sceneShots.find(s=>s.id===el.dataset.workshopShot);el.classList.toggle('active',shot&&cameraKey(shot.camera)===cameraKey(p.camera));});
}

function ensureVideoMotion(image){
 if(p.videoMotion?.imageId===image.id)return;
 const end=p.plan.asset==='painter-workshop'?p.sceneShots.find(s=>s.id==='close').camera:image.camera;
 p.videoMotion={imageId:image.id,start:clone(image.camera),end:clone(end),seconds:4};
}
function initMotionGuide(){
 const image=p.takes.find(t=>t.id===p.videoImageId);if(!image)return;ensureVideoMotion(image);
 let time=0;const motion=p.videoMotion;
 const showTime=t=>{time=t;guide.set(cameraAt(motion,t));$('motionTime').value=t;$('motionTimeLabel').textContent=t.toFixed(1)+' / '+motion.seconds+'s';const lens=$('motionLens'),focal=Math.round(cameraAt(motion,t).focal);if(![...lens.options].some(o=>+o.value===focal))lens.add(new Option(focal+' mm',focal));lens.value=String(focal);};
 guide=new Guide($('guideViewport'),camera=>{const end=time>=motion.seconds/2;time=end?motion.seconds:0;motion[end?'end':'start']=clone(camera);$('motionTime').value=time;$('motionTimeLabel').textContent=time.toFixed(1)+' / '+motion.seconds+'s';queueSave();});
 guide.load(p.plan,16/9);guide.renderer.domElement.addEventListener('pointerdown',()=>setWorkspaceFocus('edit'));showTime(0);
 const stop=()=>{cancelAnimationFrame(motionFrame);motionFrame=null;$('playMotion').textContent='▶';};
 on('motionTime',e=>{setWorkspaceFocus('edit');stop();showTime(+e.target.value);},'input');
 on('motionLens',e=>{const end=time>=motion.seconds/2;time=end?motion.seconds:0;motion[end?'end':'start'].focal=+e.target.value;showTime(time);queueSave();},'change');
 on('motionOriginal',()=>{stop();motion.start=clone(image.camera);showTime(0);queueSave();});
 on('motionDuration',e=>{stop();motion.seconds=+e.target.value;$('motionTime').max=motion.seconds;$('motionDurationLabel').textContent=motion.seconds+'s';showTime(Math.min(time,motion.seconds));queueSave();},'input');
 on('playMotion',()=>{if(motionFrame){stop();return;}const start=performance.now();$('playMotion').textContent='Ⅱ';const tick=()=>{const t=Math.min(motion.seconds,(performance.now()-start)/1000);showTime(t);if(t<motion.seconds)motionFrame=requestAnimationFrame(tick);else stop();};motionFrame=requestAnimationFrame(tick);});
 on('downloadMotion',async()=>{stop();$('downloadMotion').disabled=true;try{const blob=await recordGuide(motion.seconds);download(blob,'shotfix-camera-guide.webm');}finally{if($('downloadMotion'))$('downloadMotion').disabled=false;}});
}

function demoVideoControls(){
 const image=p.takes.find(t=>t.id===p.videoImageId),output=p.demoMedia.outputs[image?.mockShotId];
 if(!output)return '<p class="notes">Choose a demo image take to preview its video.</p>';
 const seconds=Math.min(p.demoPreviewSeconds||output.duration,output.duration);
 return `<div class="stack"><div class="row"><label for="demoPreviewLength">Preview length</label><span id="demoPreviewValue">${seconds.toFixed(2)} s</span></div><input id="demoPreviewLength" type="range" min="0.25" max="${output.duration}" step="0.01" value="${seconds}" aria-label="Sample video preview length"><small>Supplied sample · ${output.duration.toFixed(2)} s full clip</small></div>`;
}
function bindDemoPlayback(){
 if(!p?.demoMode||mode!=='video')return;
 const video=$('resultMedia')?.querySelector('video');if(!video)return;
 const limit=selected()?.origin==='workflow-result'?video.duration:(p.demoPreviewSeconds||video.duration);video.onplay=()=>{if(video.currentTime>=limit-.03)video.currentTime=0;};
 video.ontimeupdate=()=>{if(video.currentTime>=limit){video.pause();video.currentTime=0;}};
}
async function showDemoResult(){
 if(busy)return;const projectId=p.id,sourceId=p.sourceId,kind=mode,requestedCamera=clone(p.camera),requestedPlan=clone(p.plan);
 let shot=kind==='image'?demoShotForCamera(p.camera,p.sceneShots):null;
 const image=kind==='video'?p.takes.find(t=>t.id===p.videoImageId):null;
 if(kind==='video')shot=p.sceneShots.find(s=>s.id===image?.mockShotId);
 if(!shot||!p.demoMedia.outputs[shot.id]){
  if(kind==='video')return toast('Choose a Low side or Brush close-up mock image first.');
  return toast('Import your generated image for this camera view. The demo only contains supplied sample results.');
 }
 busy=true;if($('generate'))$('generate').disabled=true;
 try{
  const fixture=p.demoMedia.outputs[shot.id];if(kind==='video'&&fixture.origin==='workflow-result'&&p.videoMotion&&(p.videoMotion.seconds!==4||cameraKey(p.videoMotion.start)!==cameraKey(shot.camera)||cameraKey(p.videoMotion.end)!==cameraKey(p.sceneShots.find(s=>s.id==='close').camera)))return toast('This camera motion differs from the recorded result. Open workflow controls to export or generate your edited motion.');const response=await fetch('./assets/private/painter-workshop/'+(kind==='image'?fixture.image:fixture.video));
  if(!response.ok)throw Error('The supplied sample could not be loaded.');const blob=await response.blob();
  if(p.id!==projectId||p.sourceId!==sourceId||mode!==kind)return;
  const take=takeSnapshot(p,blob,kind,fixture.origin||'mock');take.camera=requestedCamera;take.plan=requestedPlan;take.mockShotId=shot.id;take.label=fixture.label;
  if(kind==='video'){take.parentTakeId=image.id;take.duration=fixture.duration;}
  p.takes.push(take);restoreTake(p,take);workspaceFocus='review';await save();render();
  toast(fixture.origin==='workflow-result'?'Recorded Comfy workflow result loaded. No new generation or credits used.':kind==='image'?'Mock image preview loaded. Select this take, then Create video.':'Mock video loaded from the supplied clip. No credits used.');
 }finally{busy=false;if($('generate'))$('generate').disabled=false;}
}

async function sample(){newProject();const image=new Image();image.src='./assets/design-study.png';await image.decode();const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=720;canvas.getContext('2d').drawImage(image,image.width*.331,image.height*.133,image.width*.646,image.height*.645,0,0,1280,720);const blob=await blobCanvas(canvas);Object.assign(p,{sourceBlob:blob,posterBlob:blob,sourceType:'image',sourceName:'evening-study.png',name:'Evening study',width:1280,height:720,duration:0,seconds:4,example:true,plan:{version:1,method:'prepared-example',room:'arch',horizon:.45,subjects:[{kind:'person',x:.52,bottom:.93,height:.81,width:.22}]}});await save();route='input';render();}
$('sourcePicker').onchange=wrap(async e=>{const f=e.target.files[0];if(f)await loadSource(f);e.target.value='';});$('referencePicker').onchange=wrap(async e=>{if(!p?.posterBlob)return;for(const file of [...e.target.files].slice(0,6-p.references.length)){if(file.size>12*1024*1024)throw Error('Reference images must be under 12 MB.');p.references.push({name:file.name,blob:await blobCanvas(await frameCanvas(file))});}e.target.value='';await save();render();});$('resultPicker').onchange=wrap(async e=>{await importResult(e.target.files[0]);e.target.value='';});$('planPicker').onchange=wrap(async e=>{const file=e.target.files[0];if(!file)return;const raw=JSON.parse(await file.text());p.plan=validatePlan(raw.plan||raw);p.camera={az:0,el:5,focal:35,distance:6};await save();$('modal').close();route='editor';render();e.target.value='';toast('Imported a validated scene plan.');});
$('runtimeSettings').onclick=wrap(settingsDialog);$('exportProject').onclick=wrap(exportProject);$('undo').onclick=wrap(async()=>{if(!undo.length)return;Object.assign(p.camera,undo.pop());guide?.set(p.camera);await save();if($('cameraStatus'))$('cameraStatus').textContent=cameraLabel();});$('videoMode').onclick=wrap(toggleVideoMode);
